'use strict';

// MODULES //

var tape = require( 'tape' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var whileEach = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof whileEach, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function invokes a callback function for the element of a 0-dimensional ndarray while a test condition is true', function test( t ) {
	var expected;
	var values;
	var x;

	values = [];
	x = scalar2ndarray( 4.0, {
		'dtype': 'float64'
	});
	whileEach( [ x ], predicate, fcn );

	expected = [ 4.0 ];
	t.deepEqual( values, expected, 'returns expected value' );

	values = [];
	x = scalar2ndarray( 3.0, {
		'dtype': 'float64'
	});
	whileEach( [ x ], predicate, fcn );

	expected = [];
	t.deepEqual( values, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return v % 2.0 === 0.0;
	}

	function fcn( v ) {
		values.push( v );
	}
});

tape( 'the function invokes a callback function for the element of a 0-dimensional ndarray while a test condition is true (accessors)', function test( t ) {
	var expected;
	var values;
	var x;

	values = [];
	x = scalar2ndarray( new Complex128( 4.0, 0.0 ), {
		'dtype': 'complex128'
	});
	whileEach( [ x ], predicate, fcn );

	expected = [
		[ 4.0, 0.0 ]
	];
	t.deepEqual( values, expected, 'returns expected value' );

	values = [];
	x = scalar2ndarray( new Complex128( 3.0, 0.0 ), {
		'dtype': 'complex128'
	});
	whileEach( [ x ], predicate, fcn );

	expected = [];
	t.deepEqual( values, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return real( v ) % 2.0 === 0.0;
	}

	function fcn( v ) {
		values.push( [ real( v ), imag( v ) ] );
	}
});

tape( 'the function supports specifying the callback execution context (0-dimensional)', function test( t ) {
	var expected;
	var indices;
	var arrays;
	var values;
	var ctx;
	var x;

	x = scalar2ndarray( 4.0, {
		'dtype': 'float64'
	});

	indices = [];
	values = [];
	arrays = [];

	ctx = {
		'count': 0
	};
	whileEach( [ x ], predicate, fcn, ctx );

	t.strictEqual( ctx.count, 1, 'returns expected value' );

	expected = [ 4.0 ];
	t.deepEqual( values, expected, 'returns expected value' );

	expected = [ [] ];
	t.deepEqual( indices, expected, 'returns expected value' );

	expected = [ x ];
	t.deepEqual( arrays, expected, 'returns expected value' );

	t.end();

	function predicate() {
		return true;
	}

	function fcn( v, idx, arr ) {
		this.count += 1; // eslint-disable-line no-invalid-this
		values.push( v );
		indices.push( idx );
		arrays.push( arr );
	}
});

tape( 'the function supports specifying the callback execution context (0-dimensional, predicate returns false)', function test( t ) {
	var indices;
	var arrays;
	var values;
	var ctx;
	var x;

	x = scalar2ndarray( 4.0, {
		'dtype': 'float64'
	});

	indices = [];
	values = [];
	arrays = [];

	ctx = {
		'count': 0
	};
	whileEach( [ x ], predicate, fcn, ctx );

	t.strictEqual( ctx.count, 0, 'returns expected value' );
	t.deepEqual( values, [], 'returns expected value' );
	t.deepEqual( indices, [], 'returns expected value' );
	t.deepEqual( arrays, [], 'returns expected value' );

	t.end();

	function predicate() {
		return false;
	}

	function fcn( v, idx, arr ) {
		this.count += 1; // eslint-disable-line no-invalid-this
		values.push( v );
		indices.push( idx );
		arrays.push( arr );
	}
});
